<?php

use Modules\Core\Models\User;use Modules\Inventory\Models\StockBalance;use Modules\Inventory\Models\StockReservation;use Modules\Inventory\Services\InventoryTransactionService;use Modules\MasterData\Models\Material;use Modules\MasterData\Models\Operation;use Modules\MasterData\Models\Style;use Modules\MasterData\Models\Uom;use Modules\MasterData\Models\Warehouse;use Modules\ProductDev\Models\CostSheet;use Modules\ProductDev\Services\BomService;use Modules\ProductDev\Services\RoutingService;use Modules\Production\Services\ProductionOrderService;
function moFixture(float$stockQty,float$per=2,float$soQty=100):array{$u=User::factory()->create(['company_id'=>1]);$m=Uom::create(['company_id'=>1,'code'=>'MTR'.substr(uniqid(),-3),'name'=>'Meter']);$f=Material::create(['company_id'=>1,'code'=>'FAB-'.uniqid(),'name'=>'Twill','type'=>'FABRIC','tracking_level'=>'LOT']);$s=Style::create(['company_id'=>1,'style_no'=>'ST-'.uniqid(),'category'=>'WOVEN']);$bs=app(BomService::class);$bv=$bs->createVersion($s->id,[['material_id'=>$f->id,'qty_per_pcs'=>$per,'uom_id'=>$m->id]],$u);$bs->markApproved($bv);$op=Operation::create(['company_id'=>1,'code'=>'OP-'.uniqid(),'name'=>'Jahit']);$rs=app(RoutingService::class);$rv=$rs->createVersion($s->id,[['operation_id'=>$op->id,'smv'=>10]],$u);$rs->markApproved($rv);CostSheet::create(['company_id'=>1,'doc_no'=>'COST-'.uniqid(),'style_id'=>$s->id,'bom_version_id'=>$bv->id,'routing_version_id'=>$rv->id,'version'=>1,'fabric_cost'=>$per,'cm_cost'=>1,'overhead_cost'=>.5,'fob_price'=>$per+2,'status'=>'APPROVED','created_by'=>$u->id]);[$so]=erpConfirmedSo($u,$s,$soQty,12);$w=Warehouse::create(['company_id'=>1,'code'=>'RM-'.substr(uniqid(),-3),'name'=>'RM','type'=>'RM']);if($stockQty>0)app(InventoryTransactionService::class)->post('OPENING',['company_id'=>1,'source_document_type'=>'tests','source_document_id'=>1],[['material_id'=>$f->id,'warehouse_id'=>$w->id,'qty'=>$stockQty,'uom_id'=>$m->id,'unit_cost'=>10]],$u);return[$u,$f,$m,$s,$so,$w];}
test('MO snapshot BOM routing dan standard cost',function(){[$u,,,$s,$so]=moFixture(0,2,250);$mos=app(ProductionOrderService::class)->createFromSalesOrder($so,$u);expect($mos)->toHaveCount(1);$mo=$mos[0];expect($mo->status)->toBe('PLANNED')->and((float)$mo->qty_planned)->toBe(250.0)->and($mo->bom_version_id)->not->toBeNull()->and($mo->routing_version_id)->not->toBeNull()->and($mo->standard_cost_snapshot_hash)->not->toBeNull();app(ProductionOrderService::class)->createFromSalesOrder($so->fresh(),$u);})->throws(RuntimeException::class);
test('release membuat hard reservation dan mempertahankan snapshot',function(){[$u,$f,,,$so,$w]=moFixture(500);$svc=app(ProductionOrderService::class);$mo=$svc->createFromSalesOrder($so,$u)[0];$hash=$mo->standard_cost_snapshot_hash;$released=$svc->release($mo,$w->id,$u);$b=StockBalance::withoutGlobalScopes()->where('material_id',$f->id)->where('warehouse_id',$w->id)->firstOrFail();$r=StockReservation::where('mo_id',$mo->id)->firstOrFail();expect($released->status)->toBe('RELEASED')->and((float)$b->reserved)->toBe(200.0)->and($b->available())->toBe(300.0)->and((float)$r->qty_reserved)->toBe(200.0)->and($released->standard_cost_snapshot_hash)->toBe($hash);});
test('shortage rollback tanpa reservasi parsial',function(){[$u,$f,,,$so,$w]=moFixture(150);$svc=app(ProductionOrderService::class);$mo=$svc->createFromSalesOrder($so,$u)[0];expect(fn()=>$svc->release($mo,$w->id,$u))->toThrow(RuntimeException::class,'BR-040');expect(StockReservation::where('mo_id',$mo->id)->count())->toBe(0);$b=StockBalance::withoutGlobalScopes()->where('material_id',$f->id)->firstOrFail();expect((float)$b->reserved)->toBe(0.0)->and($mo->fresh()->status)->toBe('PLANNED');});
test('unrelease melepas reservasi tetapi snapshot tetap',function(){[$u,$f,,,$so,$w]=moFixture(500);$svc=app(ProductionOrderService::class);$mo=$svc->release($svc->createFromSalesOrder($so,$u)[0],$w->id,$u);$hash=$mo->standard_cost_snapshot_hash;$back=$svc->unrelease($mo,$u);$b=StockBalance::withoutGlobalScopes()->where('material_id',$f->id)->firstOrFail();expect($back->status)->toBe('PLANNED')->and((float)$b->reserved)->toBe(0.0)->and($back->standard_cost_snapshot_hash)->toBe($hash);});
